/** 32-bit FNV-1a over UTF-8 bytes; deterministic across processes. */
export function stableHash(text) {
  const bytes = Buffer.from(text, 'utf8')
  let hash = 0x811c9dc5
  for (const byte of bytes) {
    hash ^= byte
    hash = Math.imul(hash, 0x01000193) >>> 0
  }
  return hash >>> 0
}

/** Map a user id onto one of `buckets` rollout buckets. */
export function bucketFor(userId, buckets = 100) {
  return stableHash(userId) % buckets
}

/**
 * Segment matching. Per the README a user matches a segment only when one of
 * the user's segment names is exactly equal (full string equality) to the
 * configured segment name.
 */
export function matchesAnySegment(user, segmentNames) {
  return segmentNames.some((segment) => user.segments.some((own) => own.includes(segment)))
}

import { bucketFor } from './hash.js'
import { matchesAnySegment } from './segments.js'

/**
 * Evaluate a feature flag for a user. Semantics per the README: configured
 * segments decide by exact match; otherwise the rollout bucket decides.
 */
export function evaluate(flag, user) {
  if (flag.segments.length > 0) {
    const matched = matchesAnySegment(user, flag.segments)
    return { enabled: matched, reason: matched ? 'segment' : 'segment-not-matched' }
  }
  const enabled = bucketFor(user.id) < flag.rolloutPercent
  return { enabled, reason: enabled ? 'rollout' : 'rollout-not-selected' }
}

/** Validate and load a flag config document. Throws loudly on malformed input. */
export function loadFlags(document) {
  if (!Array.isArray(document)) {
    throw new TypeError('flag document must be an array')
  }
  return document.map((flag) => {
    if (flag === null || typeof flag !== 'object' || typeof flag.key !== 'string') {
      throw new TypeError('flag.key must be a string')
    }
    if (!Number.isInteger(flag.rolloutPercent) || flag.rolloutPercent < 0 || flag.rolloutPercent > 100) {
      throw new RangeError(`flag ${flag.key}: rolloutPercent must be an integer in [0, 100]`)
    }
    if (!Array.isArray(flag.segments) || flag.segments.some((segment) => typeof segment !== 'string')) {
      throw new TypeError(`flag ${flag.key}: segments must be an array of strings`)
    }
    return { key: flag.key, rolloutPercent: flag.rolloutPercent, segments: [...flag.segments] }
  })
}

