/**
 * Segment matching. Per the README a user matches a segment only when one of
 * the user's segment names is exactly equal (full string equality) to the
 * configured segment name.
 */
export function matchesAnySegment(user, segmentNames) {
  return segmentNames.some((segment) => user.segments.some((own) => own.includes(segment)))
}

import { bucketFor } from './hash.js'
import { matchesAnySegment } from './segments.js'

/**
 * Evaluate a feature flag for a user. Semantics per the README: configured
 * segments decide by exact match; otherwise the rollout bucket decides.
 */
export function evaluate(flag, user) {
  if (flag.segments.length > 0) {
    const matched = matchesAnySegment(user, flag.segments)
    return { enabled: matched, reason: matched ? 'segment' : 'segment-not-matched' }
  }
  const enabled = bucketFor(user.id) < flag.rolloutPercent
  return { enabled, reason: enabled ? 'rollout' : 'rollout-not-selected' }
}

/** Validate and load a flag config document. Throws loudly on malformed input. */
export function loadFlags(document) {
  if (!Array.isArray(document)) {
    throw new TypeError('flag document must be an array')
  }
  return document.map((flag) => {
    if (flag === null || typeof flag !== 'object' || typeof flag.key !== 'string') {
      throw new TypeError('flag.key must be a string')
    }
    if (!Number.isInteger(flag.rolloutPercent) || flag.rolloutPercent < 0 || flag.rolloutPercent > 100) {
      throw new RangeError(`flag ${flag.key}: rolloutPercent must be an integer in [0, 100]`)
    }
    if (!Array.isArray(flag.segments) || flag.segments.some((segment) => typeof segment !== 'string')) {
      throw new TypeError(`flag ${flag.key}: segments must be an array of strings`)
    }
    return { key: flag.key, rolloutPercent: flag.rolloutPercent, segments: [...flag.segments] }
  })
}

/** 32-bit FNV-1a over UTF-8 bytes; deterministic across processes. */
export function stableHash(text) {
  const bytes = Buffer.from(text, 'utf8')
  let hash = 0x811c9dc5
  for (const byte of bytes) {
    hash ^= byte
    hash = Math.imul(hash, 0x01000193) >>> 0
  }
  return hash >>> 0
}

/** Map a user id onto one of `buckets` rollout buckets. */
export function bucketFor(userId, buckets = 100) {
  return stableHash(userId) % buckets
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { matchesAnySegment } from '../src/segments.js'

test('segments: matching is exact full-string equality', () => {
  const user = { id: 'u1', segments: ['beta-testers', 'staff'] }
  assert.equal(matchesAnySegment(user, ['beta']), false, '"beta" must not substring-match "beta-testers"')
  assert.equal(matchesAnySegment(user, ['staff']), true)
  assert.equal(matchesAnySegment(user, ['Beta']), false)
})

test('segments: empty user segments never match', () => {
  const user = { id: 'u2', segments: [] }
  assert.equal(matchesAnySegment(user, ['beta']), false)
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { evaluate } from '../src/flags.js'
import { loadFlags } from '../src/config.js'
import { bucketFor } from '../src/hash.js'

test('flags: segment membership decides over rollout, by exact match only', () => {
  // rolloutPercent 0: only an exact segment match may enable the flag.
  // The user carries "beta-testers", NOT "beta" — the flag must stay disabled.
  const flag = { key: 'beta', rolloutPercent: 0, segments: ['beta'] }
  const user = { id: 'user-42', segments: ['beta-testers', 'staff'] }
  assert.deepEqual(evaluate(flag, user), { enabled: false, reason: 'segment-not-matched' })
})

test('flags: exact segment match enables', () => {
  const flag = { key: 'staff-only', rolloutPercent: 0, segments: ['staff'] }
  const user = { id: 'user-99', segments: ['staff'] }
  assert.deepEqual(evaluate(flag, user), { enabled: true, reason: 'segment' })
})

test('flags: rollout bucket decides without segments', () => {
  const flag = { key: 'wide', rolloutPercent: 100, segments: [] }
  assert.deepEqual(evaluate(flag, { id: 'user-42', segments: ['beta-testers'] }), {
    enabled: true,
    reason: 'rollout',
  })
  const closed = { key: 'closed', rolloutPercent: 0, segments: [] }
  assert.deepEqual(evaluate(closed, { id: 'user-42', segments: [] }), {
    enabled: false,
    reason: 'rollout-not-selected',
  })
})

test('flags: rollout honours the pinned bucket of the user', () => {
  // bucketFor('user-42') === 99 (frozen in hash.test.js).
  assert.equal(bucketFor('user-42'), 99)
  assert.equal(evaluate({ key: 'f', rolloutPercent: 99, segments: [] }, { id: 'user-42', segments: [] }).enabled, false)
  assert.equal(evaluate({ key: 'f', rolloutPercent: 100, segments: [] }, { id: 'user-42', segments: [] }).enabled, true)
})

test('config: rejects rolloutPercent out of range', () => {
  assert.throws(() => loadFlags([{ key: 'x', rolloutPercent: 101, segments: [] }]), RangeError)
  assert.throws(() => loadFlags([{ key: 'x', rolloutPercent: -1, segments: [] }]), RangeError)
  assert.throws(() => loadFlags([{ key: 'x', rolloutPercent: 50.5, segments: [] }]), RangeError)
})

test('config: returns defensive copies', () => {
  const source = [{ key: 'x', rolloutPercent: 10, segments: ['a'] }]
  const [flag] = loadFlags(source)
  flag.segments.push('b')
  assert.deepEqual(source[0].segments, ['a'])
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { stableHash, bucketFor } from '../src/hash.js'

test('hash: deterministic across calls', () => {
  assert.equal(stableHash('user-42'), stableHash('user-42'))
  const bucket = bucketFor('user-42')
  assert.ok(Number.isInteger(bucket) && bucket >= 0 && bucket < 100)
})

test('hash: pinned bucket values (FNV-1a, 100 buckets)', () => {
  assert.equal(bucketFor('user-42'), 99)
  assert.equal(bucketFor('user-99'), 31)
  assert.equal(stableHash('alice'), 2267157479)
})

test('hash: buckets stay in range for assorted ids', () => {
  for (const id of ['a', 'bob', 'carol', 'user-7', 'someone-with-a-long-id-123456']) {
    const bucket = bucketFor(id)
    assert.ok(bucket >= 0 && bucket < 100, `${id} -> ${bucket}`)
  }
})

